'use client';

import React, { useState } from 'react';
import { useApp } from '@/context/AppContext';

export default function FreeTrialLog() {
  const { currentUser, freeTrials, addFreeTrial, toggleFreeTrialStatus, rates } = useApp();

  const [showModal, setShowModal] = useState(false);
  const [studentName, setStudentName] = useState('');
  const [lesson, setLesson] = useState('');
  const [date, setDate] = useState(new Date().toISOString().split('T')[0]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!studentName.trim() || !lesson.trim()) {
      alert('Nama murid dan materi trial wajib diisi!');
      return;
    }

    addFreeTrial({
      studentName,
      lesson,
      date,
    });

    setStudentName('');
    setLesson('');
    setShowModal(false);
  };

  const trialFee = rates.baseFees['Free Trial'] || 25000;

  // Filter tampilan jika role tutor hanya melihat riwayatnya sendiri atau seluruhnya
  const displayedTrials =
    currentUser?.role === 'tutor'
      ? freeTrials.filter((ft) => ft.tutorId === currentUser.id)
      : freeTrials;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div>
          <h2 className="text-xl font-bold text-slate-800">Free Trial Log</h2>
          <p className="text-xs text-slate-500 mt-1">
            Pencatatan sesi uji coba belajar gratis. Fee per sesi trial: <strong>Rp {trialFee.toLocaleString('id-ID')}</strong>.
          </p>
        </div>

        <button
          onClick={() => setShowModal(true)}
          className="px-4 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-semibold shadow-sm shadow-blue-200 transition-all flex items-center gap-2 self-start md:self-auto"
        >
          <span>🎯</span> + Isi Absen Free Trial
        </button>
      </div>

      {/* Tabel Data Free Trial */}
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse text-xs">
            <thead>
              <tr className="bg-slate-50 border-b border-slate-200 text-slate-500 font-bold uppercase tracking-wider">
                <th className="py-3.5 px-4">Tanggal</th>
                <th className="py-3.5 px-4">Nama Murid</th>
                <th className="py-3.5 px-4">Tutor Pengajar</th>
                <th className="py-3.5 px-4">Materi / Lesson</th>
                <th className="py-3.5 px-4 text-center">Status</th>
                {currentUser?.role === 'admin' && <th className="py-3.5 px-4 text-center">Aksi Verifikasi</th>}
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {displayedTrials.length === 0 ? (
                <tr>
                  <td colSpan={6} className="py-8 text-center text-slate-400">
                    Belum ada riwayat sesi free trial yang tercatat.
                  </td>
                </tr>
              ) : (
                displayedTrials.map((ft) => (
                  <tr key={ft.id} className="hover:bg-slate-50/70 transition-colors">
                    <td className="py-3.5 px-4 font-semibold text-slate-700 whitespace-nowrap">{ft.date}</td>
                    <td className="py-3.5 px-4 font-bold text-slate-800">{ft.studentName}</td>
                    <td className="py-3.5 px-4 text-slate-600">{ft.tutorName}</td>
                    <td className="py-3.5 px-4 text-slate-600">{ft.lesson}</td>
                    <td className="py-3.5 px-4 text-center">
                      <span
                        className={`inline-block px-2.5 py-1 rounded-full text-[10px] font-bold ${
                          ft.status === 'completed'
                            ? 'bg-emerald-50 text-emerald-700 border border-emerald-200'
                            : 'bg-amber-50 text-amber-700 border border-amber-200'
                        }`}
                      >
                        {ft.status === 'completed' ? '✓ Terverifikasi' : '⏳ Pending'}
                      </span>
                    </td>
                    {currentUser?.role === 'admin' && (
                      <td className="py-3.5 px-4 text-center">
                        <button
                          onClick={() => toggleFreeTrialStatus(ft.id)}
                          className={`px-3 py-1 rounded-lg text-[11px] font-semibold transition-all ${
                            ft.status === 'completed'
                              ? 'text-amber-600 hover:bg-amber-50'
                              : 'text-emerald-600 hover:bg-emerald-50'
                          }`}
                        >
                          {ft.status === 'completed' ? 'Set Pending' : 'Verifikasi'}
                        </button>
                      </td>
                    )}
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Modal Input Free Trial */}
      {showModal && (
        <div className="fixed inset-0 bg-slate-900/40 backdrop-blur-sm z-50 flex items-center justify-center p-4">
          <div className="bg-white rounded-3xl max-w-md w-full p-6 shadow-2xl space-y-4">
            <div className="flex items-center justify-between border-b pb-3">
              <h3 className="font-bold text-slate-800 text-base">Input Absen Free Trial</h3>
              <button onClick={() => setShowModal(false)} className="text-slate-400 hover:text-slate-600">✕</button>
            </div>

            <form onSubmit={handleSubmit} className="space-y-3.5">
              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Nama Calon Murid</label>
                <input
                  type="text"
                  placeholder="Misal: Kevin Pratama"
                  value={studentName}
                  onChange={(e) => setStudentName(e.target.value)}
                  className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Tanggal Trial</label>
                <input
                  type="date"
                  value={date}
                  onChange={(e) => setDate(e.target.value)}
                  className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-600 mb-1">Materi / Pengenalan yang Diberikan</label>
                <textarea
                  rows={3}
                  placeholder="Misal: Placement test singkat & ice breaking phonics"
                  value={lesson}
                  onChange={(e) => setLesson(e.target.value)}
                  className="w-full px-3 py-2 text-xs border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
                  required
                />
              </div>

              <div className="pt-3 flex justify-end gap-2 border-t">
                <button
                  type="button"
                  onClick={() => setShowModal(false)}
                  className="px-4 py-2 border rounded-xl text-xs font-semibold text-slate-600 hover:bg-slate-50"
                >
                  Batal
                </button>
                <button
                  type="submit"
                  className="px-5 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-xs font-semibold shadow-sm"
                >
                  Simpan Absen Trial
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}